170	    func loginWithQRCode(data: Data) -> QRLoginProgressPublisher {
171	        let progressSubject = CurrentValueSubject<QRLoginProgress, AuthenticationServiceError>(.starting)
172	        
173	        let qrData: QrCodeData
174	        do {
175	            qrData = try QrCodeData.fromBytes(bytes: data)
176	        } catch {
177	            MXLog.error("QRCode decode error: \(error)")
178	            progressSubject.send(completion: .failure(.qrCodeError(.invalidQRCode)))
179	            return progressSubject.asCurrentValuePublisher()
180	        }
181	        
182	        // n.b. We rely on the SDK checking that the intent of the QR is suitable for us to login with.
183	        
184	        // Future versions of the QR should always give us the baseUrl
185	        guard let scannedServerNameOrBaseUrl = qrData.baseUrl() ?? qrData.serverName() else {
186	            // With the older version of QR we treat the presence of serverName as meaning that the other device
187	            // is not signed in.
188	            MXLog.error("The QR code is from a device that is not yet signed in.")
189	            progressSubject.send(completion: .failure(.qrCodeError(.deviceNotSignedIn)))
190	            return progressSubject.asCurrentValuePublisher()
191	        }
192	
193	        // n.b. We deliberatley don't check whether the received server is in our appSettings.accountProviders
194	        
195	        let listener = SDKListener { progress in
196	            guard let progress = QRLoginProgress(rustProgress: progress) else { return }
197	            progressSubject.send(progress)
198	        }
199	        
200	        Task {
201	            do {
202	                let client = try await makeClient(homeserverAddress: scannedServerNameOrBaseUrl)
203	                let qrCodeHandler = client.newLoginWithQrCodeHandler(oidcConfiguration: appSettings.oidcConfiguration.rustValue)
204	                try await qrCodeHandler.scan(qrCodeData: qrData, progressListener: listener)
205	                
206	                switch await userSession(for: client) {
207	                case .success(let userSession):
208	                    progressSubject.send(.signedIn(userSession))
209	                case .failure(let error):
210	                    progressSubject.send(completion: .failure(error))
211	                }
212	            } catch let error as HumanQrLoginError {
213	                MXLog.error("QRCode login error: \(error)")
214	                progressSubject.send(completion: .failure(error.serviceError))
215	            } catch RemoteSettingsError.elementProRequired(let serverName) {
216	                progressSubject.send(completion: .failure(.elementProRequired(serverName: serverName)))
217	            } catch {
218	                MXLog.error("QRCode login unknown error: \(error)")
219	                progressSubject.send(completion: .failure(.qrCodeError(.unknown)))
220	            }
221	        }
222	        
223	        return progressSubject.asCurrentValuePublisher()
224	    }
